        ]
      },
      {
        "name": "自动链接识别",
        "description": "autolink 与 autolink_html 在已解析的 HTML 树中扫描 http(s)/mailto 文本并自动包裹 a 标签，支持自定义正则、例外元素与主机黑名单。",
        "evidence": [
          "lxml_html_clean/clean.py:autolink",
          "lxml_html_clean/clean.py:autolink_html",
          "lxml_html_clean/clean.py:_link_text"
